'use strict';class GalleryTemplates{static PhotoGalleryItem({activePage:c,metadata:b,overlayData:a,uuid:d}){return`
        <div id="photoThumbnailContainer${b.id}" class="photo-thumbnail-container photo-thumbnail" style="width:${b.thumbnailSmallWidth}px;height:${b.thumbnailSmallHeight}px;padding-left:0;padding-right:0;">
            <span class="lightGalleryIndexAnchor"></span>
            <img loading="lazy" data-smallthumb="${encodeURI(b.thumbnailUrlSmall)}?v=${d}" data-xsmallthumb="${null===b.thumbnailUrlExtraSmall?"":encodeURI(b.thumbnailUrlExtraSmall)}?v=${d}" src="${encodeURI(b.thumbnailUrlSmall)}?v=${d}" class="photo-thumbnail-image" id="image${b.id}" width="${b.thumbnailSmallWidth}" height="${b.thumbnailSmallHeight}" style="background-color:lightgray;">
            <input type="hidden" name="filename${b.id}" id="filename${b.id}" value="${b.fileName}">
            <input type="hidden" name="thumbnailCentered${b.id}" id="thumbnailCentered${b.id}" value="${encodeURI(b.thumbnailUrlCentered)}">
            
            ${"share"===c?`<div class="thumbnail-bl" id="tnbl${b.id}">
                <a href="/api/v1${b.type.includes("video")?"/video/":"/image/"}${b.id}/download" id="download${b.id}">
                    <span class="bi-download" style="font-size: 1rem;color: lightgray;"></span>
                </a>
            </div>`:""}
    
            ${a.hasOwnProperty("data")&&a.data.hasOwnProperty("overlayFlags")&&a.data.overlayFlags.hasOwnProperty("renderTopRight")&&!0===a.data.overlayFlags.renderTopRight?GalleryTemplates.getTopRightOverlay({id:b.id,overlays:a.overlays,data:a.data}):""}
            
            ${a.hasOwnProperty("data")&&a.data.hasOwnProperty("overlayFlags")&&a.data.overlayFlags.hasOwnProperty("renderTopLeft")&&!0===a.data.overlayFlags.renderTopLeft?GalleryTemplates.getTopLeftOverlay({id:b.id,overlays:a.overlays,data:a.data}):""}
            
            ${a.hasOwnProperty("data")&&a.data.hasOwnProperty("overlayFlags")&&a.data.overlayFlags.hasOwnProperty("renderBottomLeft")&&!0===a.data.overlayFlags.renderBottomLeft?GalleryTemplates.getBottomLeftOverlay({metadata:b,overlays:a.overlays,data:a.data}):""}
            
            ${a.hasOwnProperty("data")&&a.data.hasOwnProperty("overlayFlags")&&a.data.overlayFlags.hasOwnProperty("renderBottomRight")&&!0===a.data.overlayFlags.renderBottomRight?GalleryTemplates.getBottomRightOverlay({id:b.id,overlays:a.overlays,data:a.data}):""}
            
            ${a.hasOwnProperty("data")&&a.data.hasOwnProperty("overlayFlags")&&a.data.overlayFlags.hasOwnProperty("renderCenter")&&!0===a.data.overlayFlags.renderCenter?GalleryTemplates.getCenteredOverlay({id:b.id,overlays:a.overlays,data:a.data,uuid:d,activePage:c}):""}
            
        </div>
        ${"album"===c?`<span id="albummodal${b.id}" style="width:0;height:0;padding:0"></span>`:""}
        ${"person"===c?`<span id="personmodal${b.id}" style="width:0;height:0;padding:0"></span>`:""}
        
        <script type="text/javascript"${0<shashin.nonce.length?' nonce="'+shashin.nonce+'"':""}>
            shashin.setPhotoOverlays({id:"${b.id}",type:"${b.type}",lat:"${null===b.lat?"":`${b.lat}`}", lng:"${null===b.lng?"":`${b.lng}`}", year:${b.year}, month:${b.month}, day:${b.day}, fileName:"${b.fileName}", thumbnailUrlSmall:"${b.thumbnailUrlSmall}"}, "${c}");
            Util.activateMetadataListeners("${b.id}");
            $("#mediaLink${b.id}").attr("tag", "${b.id}");
            
            ${!1===a.hasOwnProperty("data")||!1===a.data.hasOwnProperty("overlayFlags")||!1===a.data.overlayFlags.hasOwnProperty("renderBottomLeft")||!1===a.data.overlayFlags.renderBottomLeft||-1!==$.inArray("isInfo",a.overlays)?`
                $("#infoModalEdit${b.id}").on("click", function (e) {
                    e.preventDefault();
                    shashin.openEditMetadataModal("${b.id}");
                })
                `:`
                $("#metadataModalEdit${b.id}").on("click", function (e) {
                    e.preventDefault();
                    shashin.openEditMetadataModal("${b.id}");
                })
                `}
    
            $("#image${b.id}").on('load', function () {
                $(this).css("background-color", "transparent");
            });
            
            // Util.checkErrorImage();
        </script>        
    `}static getTopRightOverlay({id:c,overlays:b,data:a}){return`
        <div class="thumbnail-tr" id="tntr${c}">

        ${-1!==$.inArray("isVideo",b)?`
            <span class="overlayIconBackground"><span id="duration${c}">${a.duration}</span>
                <span id="video${c}" class="bi-camera-video overlayIcon" title="video"></span>
            </span>
            <br>
            `:""} 
        
        ${-1!==$.inArray("isPan",b)?`
            <span id="panorama${c}" class="bi-aspect-ratio overlayIcon overlayIconBackground" title="panorama"></span>
            <br>
            `:""}
        
        ${-1!==$.inArray("isGif",b)?`
            <span id="gif${c}" class="bi-layers overlayIcon overlayIconBackground" title="gif"></span>
            <br>
            `:""}
        
        ${-1!==$.inArray("isTagged",b)?'\n            <span class="bi-bookmark-fill overlayIconBackground" style="font-size: 1rem;color: lightsalmon;"></span>\n            ':""}
    
        </div>
    `}static getTopLeftOverlay({id:c}){return`
        <div class="thumbnail-tl" id="tntl${c}">
            <a href="#" id="select${c}">
                <span id="tlicon${c}" class="bi-circle" style="font-size: 1rem;color: lightgray;"></span>
            </a>
        </div>
    `}static getBottomRightOverlay({id:c,overlays:b,data:a}){return`
        <div class="thumbnail-br" id="tnbr${c}">
            ${-1!==$.inArray("isComments",b)?`
            
            <a href="#" data-bs-toggle="modal" data-bs-target="#propalbumphotocomment${c}" class="overlayCommentIconBackground overlayCommentText">
                <span id="brcommentcount${c}">${a.albumPhotoCommentsMap.hasOwnProperty(c)?a.albumPhotoCommentsMap[c].length:"0"}</span> 
                <span id="bricon${c}" class="bi-chat-square position-relative overlayCommentIcon">
                </span>
            </a>
            `:""}
            ${-1!==$.inArray("isFavorites",b)?`
            <br>
            <a href="#" id="favorite${c}" class="text-decoration-none">
                <span class="overlayIconBackground">
                    <span id="briconcount${c}">${a.favoriteCount}</span>&nbsp;<span class="${a.favoriteIcon} overlayIcon" id="brfavoriteicon${c}"></span>
                </span>
            </a>
            `:""}
        </div>
    `}static getBottomLeftOverlay({metadata:c,overlays:b,data:a}){return`
        <div class="thumbnail-bl" id="tnbl${c.id}">
            ${-1!==$.inArray("isBlOnClickFunction",b)?`
            <br>
            <a href="#" id="${a.onClickIdPrefix}${c.id}">
                <span class="bi-journal-album" style="font-size: 1rem;color: lightgray;" title="Set as album cover"></span>
            </a>
    
            <script type="text/javascript"${0<shashin.nonce.length?' nonce="'+shashin.nonce+'"':""}>
                $("#${a.onClickIdPrefix}${c.id}").on("click", function (e) {
                    e.preventDefault();
                    ${a.blOnClickFunction}(e,"${c.id}");
                });
            </script>
            `:""}
            
            ${-1!==$.inArray("isOnClickIdPrefix",b)?`
            <br>
            <a href="#" data-bs-toggle="modal" data-bs-target="#${a.onClickIdPrefix}${c.id}">
                <span class="bi-pencil" style="font-size: 1rem;color: lightgray;"></span>
            </a>
            `:""}
            
            ${-1!==$.inArray("isInfo",b)?`
            <br>
            <a href="#" id="infoModalEdit${c.id}" tag="${c.id}">
                <span class="${null!==c.lat&&null!==c.lng?"bi-info-circle":"bi-info-square"}" style="font-size: 1rem;color: lightgray;" title="Set as album cover"></span>
            </a>
            `:""}
            
            ${-1!==$.inArray("isEditControls",b)?`
            <a href="#" id="metadataModalEdit${c.id}" data-bs-target="#propTimelinModal" tag="${c.id}">
                <span class="${a.editIcon}" style="font-size: 1rem;color: lightgray;"></span>
            </a>
            `:""}
        </div>
    `}static getCenteredOverlay({id:c,overlays:b,data:a,uuid:d,activePage:e}){return`
        <div class="thumbnail-centered" id="tncentered${c}">
    
            ${-1!==$.inArray("isVideo",b)?`
                <a class="mediaLink" id="mediaLink${c}" data-download-url="${encodeURI(a.metadata.videoUrl)}/download" 
                    ${null!==a.metadata.description?` data-sub-html="${a.metadata.description}" `:""}
                    data-metadata-id="${a.metadata.id}"
                    data-poster="${null===a.metadata.thumbnailUrlOriginal||""===a.metadata.thumbnailUrlOriginal?a.metadata.thumbnailUrlSmall:encodeURI(a.metadata.thumbnailUrlOriginal)}?v=${d}"
                    data-lg-size="${null===a.metadata.originalImageWidth||""===a.metadata.originalImageWidth?`${a.metadata.thumbnailSmallWidth}-${a.metadata.thumbnailSmallHeight}`:`${a.metadata.originalImageWidth}-${a.metadata.originalImageHeight}`}"
                    data-video=\'{"source": [{"src":"${a.metadata.videoUrl}", "type":"video/mp4"}], "attributes": {"preload": false, "controls": true, "autoplay": true}}\'>
                    ${"slideshow"!==e?'<span class="bi-play-circle" style="font-size: 4rem;color: lightgray;"></span>':""}
                </a>
                `:`
                <a class="mediaLink" id="mediaLink${c}" data-src="${a.metadata.thumbnailUrlOriginal}" href="${a.metadata.thumbnailUrlOriginal}"
                    data-download-url="${encodeURI(a.metadata.thumbnailUrlOriginal)}/download"
                    data-metadata-id="${a.metadata.id}"
                    ${null!==a.metadata.description?` data-sub-html="${a.metadata.description}" `:""}>
                    ${"slideshow"!==e?'<span class="bi-play-circle" style="font-size: 4rem;color: lightgray;"></span>':""}
                </a>
                `}
    
            <script type="text/javascript"${0<shashin.nonce.length?` nonce="${shashin.nonce}"`:""}>
                $("#mediaLink${c}").on("click", function (e) {
                    e.preventDefault();
                    ${a.cOnClickFunction}(e,${a.galleryIndex});
                });
            </script>
    
        </div>
    `}static getFoldersCard({folder:c,thumbnailUrlCentered:b,count:a,appendClass:d}){return`
        <div class="card" style="width:235px;padding-top:10px;">
            <a href="/folder/${encodeURIComponent(encodeURIComponent(c))}" style="text-decoration: none !important;color: #777777;">
                <img loading="lazy" class="card-img-top" src="${b}" width="209" height="209" style="width: 209px;height: 209px;">
            </a>
            <div class="card-body">
                <p class="card-text"><strong>${c}</strong></p>
                <p class="card-text"><small class="text-muted">${a} items</small></p>
            </div>
        </div>
        
        <span class="${d}" style="width:0;height:0;padding:0"></span>
    `}}
;
